SocialPost|null>(null);const [isBriefDetail,setIsBriefDetail]=useState(false);const [selectedBriefProject,setSelectedBriefProject]=useState("Marker Group");const [commentDraft,setCommentDraft]=useState("");const [commentThreads,setCommentThreads]=useState<Record<string,string[]>>({"The hidden cost of a delayed fire door inspection":["Can we make the checklist the main visual? The client asked for something their site teams can save."],"Weekly plan · Marker Group":["Could you add one visual reference for the carousel topic?"]});const [postActivity,setPostActivity]=useState<Record<string,PostActivityEvent[]>>({});
 const isFreelancer=role==="Eve";const freelancerProjectIds=["marker","housebuild","buildregs","irevise","fireregs"];const accessibleProjects=projects.filter(p=>!isFreelancer||freelancerProjectIds.includes(p.id));const selectedProject=projects.find(p=>p.id===selectedId&&(!isFreelancer||freelancerProjectIds.includes(p.id)))??accessibleProjects[0]??projects[0];const visibleProjects=accessibleProjects.filter(p=>(filterType==="All types"||p.type===filterType)&&p.name.toLowerCase().includes(query.toLowerCase()));
 function ping(text:string){setToast(text);window.setTimeout(()=>setToast(""),2800)}
